"""Predefined cybersecurity threat detection rules for ThreatGuard SIEM simulation."""

import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional
import pandas as pd

from detection.risk_scoring import calculate_risk_score
from detection.threat_classifier import classify_severity


@dataclass
class DetectionResult:
    """Standardized detection match generated by a detection rule."""
    rule_id: str
    rule_name: str
    category: str
    severity: str
    risk_score: int
    source_ip: str
    timestamp: str
    explanation: str
    recommended_response: str
    evidence_count: int = 1
    evidence_samples: List[str] = field(default_factory=list)


# ========================================================
# RULE IMPLEMENTATIONS
# ========================================================

class BruteForceRule:
    """RULE-AUTH-001: Detect repetitive failed authentication attempts."""
    rule_id = "RULE-AUTH-001"
    name = "Brute Force Authentication Attack"
    category = "Brute Force"
    description = (
        "Identifies repeated failed login or authentication attempts originating "
        "from the same source IP within a monitoring interval."
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "source_ip" not in df.columns:
            return results

        limit = thresholds.get("brute_force_failed_attempts", 5)

        # Identify authentication failure records
        auth_mask = (
            df["event_type"].str.contains(r"login|auth|signin|credential", case=False, na=False)
            | df["message"].str.contains(r"password|login failed|auth fail", case=False, na=False)
        )
        fail_mask = df["status"].isin(["FAILED", "FAILURE", "DENIED", "ERROR", "401", "REJECTED"])
        target_df = df[auth_mask & fail_mask]

        if target_df.empty:
            return results

        counts = target_df.groupby("source_ip").size()
        for ip, count in counts.items():
            if count >= limit:
                # Heuristic risk calculation: 70 base, scale with count
                risk = calculate_risk_score(base_weight=70, indicator_strength=0.95, frequency_multiplier=count)
                severity = classify_severity(risk)
                
                # Retrieve latest timestamp and target usernames
                sub = target_df[target_df["source_ip"] == ip]
                latest_ts = str(sub["timestamp"].iloc[-1])
                target_users = sub["username"].dropna().unique().tolist()
                users_str = f" Target usernames: {', '.join(target_users[:3])}." if target_users else ""

                explanation = (
                    f"Suspicious Indicator: Observed {count} failed authentication attempts from IP {ip}."
                    f"{users_str} Pattern strongly indicates password guessing or credential stuffing."
                )
                recommendation = (
                    "Review authentication telemetry for targeted accounts. Verify multi-factor authentication (MFA) "
                    "enforcement, apply rate limiting or temporary IP tarpit, and initiate password resets if any login subsequently succeeded."
                )

                results.append(
                    DetectionResult(
                        rule_id=self.rule_id,
                        rule_name=self.name,
                        category=self.category,
                        severity=severity,
                        risk_score=risk,
                        source_ip=str(ip),
                        timestamp=latest_ts,
                        explanation=explanation,
                        recommended_response=recommendation,
                        evidence_count=int(count),
                        evidence_samples=sub["message"].dropna().head(3).tolist(),
                    )
                )

        return results


class PortScanningRule:
    """RULE-NET-002: Detect reconnaissance port scanning across multiple destination ports."""
    rule_id = "RULE-NET-002"
    name = "Port Scanning / Service Discovery"
    category = "Port Scanning"
    description = (
        "Detects a single source IP probing multiple destination ports in sequence, "
        "suggesting port scanning or network reconnaissance."
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "source_ip" not in df.columns or "port" not in df.columns:
            return results

        port_limit = thresholds.get("port_scan_port_count", 5)

        # Valid non-zero destination ports
        port_df = df[(df["port"] > 0) & (df["port"] <= 65535)]
        if port_df.empty:
            return results

        grouped = port_df.groupby("source_ip")["port"].nunique()
        for ip, unique_ports in grouped.items():
            if unique_ports >= port_limit:
                sub = port_df[port_df["source_ip"] == ip]
                sample_ports = [str(p) for p in sub["port"].unique()[:6]]
                risk = calculate_risk_score(base_weight=60, indicator_strength=0.85, frequency_multiplier=unique_ports)
                severity = classify_severity(risk)
                latest_ts = str(sub["timestamp"].iloc[-1])

                explanation = (
                    f"Suspicious Indicator: Source IP {ip} connected to {unique_ports} distinct destination ports "
                    f"({', '.join(sample_ports)}...). Indicates automated network scanning or port enumeration."
                )
                recommendation = (
                    "Examine perimeter firewall access logs for systematic sweep patterns. Verify exposed services "
                    "are necessary and patched, drop unauthorized unsolicited packets, and configure dynamic blacklisting if scanning persists."
                )

                results.append(
                    DetectionResult(
                        rule_id=self.rule_id,
                        rule_name=self.name,
                        category=self.category,
                        severity=severity,
                        risk_score=risk,
                        source_ip=str(ip),
                        timestamp=latest_ts,
                        explanation=explanation,
                        recommended_response=recommendation,
                        evidence_count=int(unique_ports),
                        evidence_samples=[f"Port {p}" for p in sample_ports],
                    )
                )

        return results


class SqlInjectionRule:
    """RULE-WEB-003: Detect SQL Injection signatures in query parameters or payload messages."""
    rule_id = "RULE-WEB-003"
    name = "SQL Injection (SQLi) Attempt"
    category = "SQL Injection"
    description = (
        "Identifies classical SQL injection patterns including boolean tautologies, "
        "UNION SELECT operations, comment terminators, and administrative procedures."
    )

    SQLI_PATTERN = re.compile(
        r"(?i)(?:\bUNION\s+(?:ALL\s+)?SELECT\b|'\s*OR\s*(?:'?[0-9]+'?'?\s*=\s*'?[0-9]+|'[^']*'='[^']*')|"
        r"DROP\s+TABLE|INFORMATION_SCHEMA|SLEEP\s*\(\s*\d+\s*\)|--\s*$|/\*.*?\*/|;\s*SHUTDOWN|WAITFOR\s+DELAY)",
        re.IGNORECASE,
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "message" not in df.columns:
            return results

        sqli_df = df[df["message"].astype(str).str.contains(self.SQLI_PATTERN, na=False)]
        if sqli_df.empty:
            return results

        grouped = sqli_df.groupby("source_ip")
        for ip, group in grouped:
            count = len(group)
            matched_samples = group["message"].head(3).tolist()
            risk = calculate_risk_score(base_weight=85, indicator_strength=0.98, frequency_multiplier=count)
            severity = classify_severity(risk)
            latest_ts = str(group["timestamp"].iloc[-1])

            explanation = (
                f"Suspicious Indicator: Identified {count} SQL injection signature(s) in inbound HTTP payloads from {ip}. "
                f"Payload sample: \"{matched_samples[0][:90]}\"."
            )
            recommendation = (
                "Immediately verify whether backend database utilizes parameterized prepared statements (e.g. ORM / PDO). "
                "Inspect Web Application Firewall (WAF) rule sets, validate database query audit logs for anomalies, and sanitize user input."
            )

            results.append(
                DetectionResult(
                    rule_id=self.rule_id,
                    rule_name=self.name,
                    category=self.category,
                    severity=severity,
                    risk_score=risk,
                    source_ip=str(ip),
                    timestamp=latest_ts,
                    explanation=explanation,
                    recommended_response=recommendation,
                    evidence_count=int(count),
                    evidence_samples=matched_samples,
                )
            )

        return results


class XssRule:
    """RULE-WEB-004: Detect Cross-Site Scripting (XSS) injection attempts."""
    rule_id = "RULE-WEB-004"
    name = "Cross-Site Scripting (XSS) Attack"
    category = "Cross-Site Scripting (XSS)"
    description = (
        "Detects unauthorized client-side script tags, DOM event handlers, "
        "and JavaScript pseudo-protocols designed to execute malicious scripts in victim browsers."
    )

    XSS_PATTERN = re.compile(
        r"(?i)(?:<\s*script\b[^>]*>.*?<\s*/\s*script\s*>|<\s*script\b|javascript\s*:|onerror\s*=|onload\s*=|"
        r"document\.cookie|<\s*iframe\b|eval\s*\()",
        re.IGNORECASE,
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "message" not in df.columns:
            return results

        xss_df = df[df["message"].astype(str).str.contains(self.XSS_PATTERN, na=False)]
        if xss_df.empty:
            return results

        grouped = xss_df.groupby("source_ip")
        for ip, group in grouped:
            count = len(group)
            samples = group["message"].head(3).tolist()
            risk = calculate_risk_score(base_weight=75, indicator_strength=0.92, frequency_multiplier=count)
            severity = classify_severity(risk)
            latest_ts = str(group["timestamp"].iloc[-1])

            explanation = (
                f"Suspicious Indicator: Detected {count} Cross-Site Scripting (XSS) script tag or handler "
                f"patterns in requests from {ip}. Sample: \"{samples[0][:90]}\"."
            )
            recommendation = (
                "Enforce strict contextual HTML entity encoding on web application outputs. Implement robust "
                "Content Security Policy (CSP) headers restricting inline script execution, and audit client input validation."
            )

            results.append(
                DetectionResult(
                    rule_id=self.rule_id,
                    rule_name=self.name,
                    category=self.category,
                    severity=severity,
                    risk_score=risk,
                    source_ip=str(ip),
                    timestamp=latest_ts,
                    explanation=explanation,
                    recommended_response=recommendation,
                    evidence_count=int(count),
                    evidence_samples=samples,
                )
            )

        return results


class SuspiciousIpRule:
    """RULE-IP-005: Detect persistent anomalous behavior or high failure rates from an IP."""
    rule_id = "RULE-IP-005"
    name = "Suspicious IP Activity"
    category = "Suspicious IP Activity"
    description = (
        "Identifies IP addresses generating abnormally frequent security errors, "
        "rejected requests, or unauthorized probing activities."
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "source_ip" not in df.columns:
            return results

        threshold = thresholds.get("suspicious_ip_threshold", 8)
        anomalous_statuses = ["DENIED", "BLOCKED", "FAILED", "FAILURE", "DROP", "REJECT", "403", "404", "500"]
        
        anom_df = df[df["status"].isin(anomalous_statuses)]
        if anom_df.empty:
            return results

        grouped = anom_df.groupby("source_ip").size()
        for ip, count in grouped.items():
            if count >= threshold:
                sub = anom_df[anom_df["source_ip"] == ip]
                risk = calculate_risk_score(base_weight=65, indicator_strength=0.85, frequency_multiplier=count)
                severity = classify_severity(risk)
                latest_ts = str(sub["timestamp"].iloc[-1])

                explanation = (
                    f"Suspicious Indicator: Source IP {ip} produced {count} security-flagged or rejected events. "
                    f"Repetitive anomalies suggest hostile reconnaissance or automated fuzzing."
                )
                recommendation = (
                    "Correlate IP with open-source threat intelligence feeds. Inspect edge reverse proxy and firewall "
                    "telemetry to evaluate blocking or rate-throttling options."
                )

                results.append(
                    DetectionResult(
                        rule_id=self.rule_id,
                        rule_name=self.name,
                        category=self.category,
                        severity=severity,
                        risk_score=risk,
                        source_ip=str(ip),
                        timestamp=latest_ts,
                        explanation=explanation,
                        recommended_response=recommendation,
                        evidence_count=int(count),
                        evidence_samples=sub["message"].dropna().head(3).tolist(),
                    )
                )

        return results


class UnauthorizedAccessRule:
    """RULE-ACCESS-006: Detect unauthorized access attempts to privileged endpoints or files."""
    rule_id = "RULE-ACCESS-006"
    name = "Unauthorized Access Attempt"
    category = "Unauthorized Access"
    description = (
        "Detects attempts to access administrative interfaces, sensitive system configuration "
        "files (e.g. /etc/passwd, .env), or restricted directories without authorization."
    )

    PRIVILEGED_PATTERN = re.compile(
        r"(?i)(?:/admin|/etc/passwd|\.\./|authorized_keys|root_access|\.env|wp-admin|config\.php|id_rsa)",
        re.IGNORECASE,
    )

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "message" not in df.columns:
            return results

        # Match privileged paths or access rejection statuses
        status_mask = df["status"].isin(["UNAUTHORIZED", "FORBIDDEN", "DENIED", "401", "403"])
        msg_mask = df["message"].astype(str).str.contains(self.PRIVILEGED_PATTERN, na=False)
        access_df = df[status_mask & msg_mask]

        if access_df.empty:
            return results

        grouped = access_df.groupby("source_ip")
        for ip, group in grouped:
            count = len(group)
            samples = group["message"].head(3).tolist()
            risk = calculate_risk_score(base_weight=80, indicator_strength=0.94, frequency_multiplier=count)
            severity = classify_severity(risk)
            latest_ts = str(group["timestamp"].iloc[-1])

            explanation = (
                f"Suspicious Indicator: Detected {count} unauthorized attempt(s) to access restricted or sensitive paths "
                f"from IP {ip}. Evidence: \"{samples[0][:80]}\"."
            )
            recommendation = (
                "Audit authorization checks and RBAC role assignments across protected endpoints. "
                "Ensure directory traversal protections are active and rotate any potentially exposed credentials."
            )

            results.append(
                DetectionResult(
                    rule_id=self.rule_id,
                    rule_name=self.name,
                    category=self.category,
                    severity=severity,
                    risk_score=risk,
                    source_ip=str(ip),
                    timestamp=latest_ts,
                    explanation=explanation,
                    recommended_response=recommendation,
                    evidence_count=int(count),
                    evidence_samples=samples,
                )
            )

        return results


class UnusualNetworkActivityRule:
    """RULE-NET-007: Detect abnormal traffic volume or high-risk backdoor port access."""
    rule_id = "RULE-NET-007"
    name = "Unusual Network Activity"
    category = "Unusual Network Activity"
    description = (
        "Identifies traffic directed at known suspicious or backdoor ports (e.g. 4444, 31337, 6667) "
        "or extreme event frequency spikes exceeding normal operational thresholds."
    )

    SUSPICIOUS_PORTS = {4444, 31337, 6667, 1337, 8888, 5555}

    def evaluate(
        self, df: pd.DataFrame, thresholds: Dict[str, Any]
    ) -> List[DetectionResult]:
        results: List[DetectionResult] = []
        if df.empty or "source_ip" not in df.columns:
            return results

        volume_threshold = thresholds.get("unusual_volume_threshold", 25)

        # 1. Backdoor port check
        if "port" in df.columns:
            port_hits = df[df["port"].isin(self.SUSPICIOUS_PORTS)]
            for ip, group in port_hits.groupby("source_ip"):
                count = len(group)
                ports_used = group["port"].unique().tolist()
                risk = calculate_risk_score(base_weight=80, indicator_strength=0.90, frequency_multiplier=count)
                severity = classify_severity(risk)
                latest_ts = str(group["timestamp"].iloc[-1])

                explanation = (
                    f"Suspicious Indicator: Source IP {ip} connected to known high-risk/backdoor port(s): {ports_used}. "
                    f"Observed {count} event(s)."
                )
                recommendation = (
                    "Inspect endpoint running on target port for potential rootkit or backdoor listener. "
                    "Enforce strict network egress/ingress filtering and capture full packet payload for forensics."
                )

                results.append(
                    DetectionResult(
                        rule_id=self.rule_id,
                        rule_name=self.name,
                        category=self.category,
                        severity=severity,
                        risk_score=risk,
                        source_ip=str(ip),
                        timestamp=latest_ts,
                        explanation=explanation,
                        recommended_response=recommendation,
                        evidence_count=int(count),
                        evidence_samples=[f"Connection to Port {p}" for p in ports_used],
                    )
                )

        # 2. Extreme volume spike check
        volume_counts = df.groupby("source_ip").size()
        for ip, count in volume_counts.items():
            if count >= volume_threshold:
                # Avoid adding if already added for backdoor port above
                if any(r.source_ip == str(ip) and r.rule_id == self.rule_id for r in results):
                    continue
                sub = df[df["source_ip"] == ip]
                risk = calculate_risk_score(base_weight=70, indicator_strength=0.80, frequency_multiplier=count)
                severity = classify_severity(risk)
                latest_ts = str(sub["timestamp"].iloc[-1])

                explanation = (
                    f"Suspicious Indicator: Abnormal activity spike from IP {ip} with {count} events "
                    f"exceeding high-volume threshold ({volume_threshold})."
                )
                recommendation = (
                    "Evaluate whether traffic corresponds to denial-of-service (DoS) flood, rogue service script, "
                    "or benign load test. Configure rate limiting on upstream load balancers."
                )

                results.append(
                    DetectionResult(
                        rule_id=self.rule_id,
                        rule_name=self.name,
                        category=self.category,
                        severity=severity,
                        risk_score=risk,
                        source_ip=str(ip),
                        timestamp=latest_ts,
                        explanation=explanation,
                        recommended_response=recommendation,
                        evidence_count=int(count),
                        evidence_samples=sub["message"].dropna().head(3).tolist(),
                    )
                )

        return results


# Registry of all active SIEM rules
ACTIVE_DETECTION_RULES = [
    BruteForceRule(),
    PortScanningRule(),
    SqlInjectionRule(),
    XssRule(),
    SuspiciousIpRule(),
    UnauthorizedAccessRule(),
    UnusualNetworkActivityRule(),
]


def get_all_rules_metadata() -> List[Dict[str, Any]]:
    """Return descriptive metadata for all registered detection rules."""
    return [
        {
            "rule_id": rule.rule_id,
            "name": rule.name,
            "category": rule.category,
            "description": rule.description,
        }
        for rule in ACTIVE_DETECTION_RULES
    ]
